package gg.projects.mobile.content;

import org.bouncycastle.util.encoders.Base64;

import java.nio.charset.StandardCharsets;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.Signature;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Feeds and signatures for the feed tests. Keys are throwaway Ed25519 pairs generated by the JDK
 * for each test run; nothing is stored.
 */
final class FeedFixtures {
    private FeedFixtures() {}

    static final String MIRROR_A = "https://feed-a.test/v1/";
    static final String MIRROR_B = "https://feed-b.test/v1/";

    /** A throwaway signing key. */
    static final class Key {
        final KeyPair pair;
        final String publicKey;
        final String keyId;

        Key() throws Exception {
            pair = KeyPairGenerator.getInstance("Ed25519").generateKeyPair();
            byte[] spki = pair.getPublic().getEncoded();
            byte[] raw = Arrays.copyOfRange(spki, spki.length - 32, spki.length);
            publicKey = Base64.toBase64String(raw);
            keyId = IndexVerifier.keyId(raw);
        }

        byte[] sign(byte[] data) throws Exception {
            return signAs(keyId, data);
        }

        /** A signature file naming {@code id} (a mislabelled one when it is not this key's). */
        byte[] signAs(String id, byte[] data) throws Exception {
            Signature signer = Signature.getInstance("Ed25519");
            signer.initSign(pair.getPrivate());
            signer.update(data);
            String sig = "{\"keyId\": \"" + id + "\", \"signature\": \"" + Base64.toBase64String(signer.sign()) + "\"}";
            return sig.getBytes(StandardCharsets.UTF_8);
        }
    }

    static byte[] utf8(String text) {
        return text.getBytes(StandardCharsets.UTF_8);
    }

    /** {@code feed.json} with the given sequence, items and events (JSON object texts). */
    static String feed(long sequence, List<String> items, List<String> events) {
        return "{\"schema\":1,\"sequence\":" + sequence + ",\"generatedAt\":\"2026-10-16T09:00:00Z\","
                + "\"items\":[" + join(items) + "],\"events\":[" + join(events) + "]}";
    }

    static String join(List<String> parts) {
        StringBuilder out = new StringBuilder();
        for (String part : parts) {
            if (out.length() > 0) out.append(',');
            out.append(part);
        }
        return out.toString();
    }

    static List<String> list(String... parts) {
        return new ArrayList<>(Arrays.asList(parts));
    }

    /** A feed item; {@code extra} is appended inside the object (start it with a comma). */
    static String item(String id, String published, String extra) {
        return "{\"id\":\"" + id + "\",\"title\":\"Haber " + id + "\",\"summary\":\"Özet\",\"body\":\"- madde\","
                + "\"category\":\"announcement\",\"tags\":[],\"publishedAt\":\"" + published + "\","
                + "\"author\":\"Projects Ekibi\",\"source\":{\"kind\":\"discord\",\"channel\":\"duyurular\","
                + "\"url\":\"https://discord.com/channels/1/2/" + id.replaceAll("[^0-9]", "") + "\"}" + extra + "}";
    }

    static String event(String id, String starts, String ends, String extra) {
        return "{\"id\":\"" + id + "\",\"title\":\"Etkinlik " + id + "\",\"startsAt\":\"" + starts + "\""
                + (ends == null ? "" : ",\"endsAt\":\"" + ends + "\"") + extra + "}";
    }

    /** A cover reference for {@code bytes} at {@code media/<sha256>.webp}. */
    static String cover(byte[] bytes, String extra) {
        String sha = Hashes.sha256Hex(bytes);
        return ",\"cover\":{\"path\":\"media/" + sha + ".webp\",\"sha256\":\"" + sha + "\",\"size\":" + bytes.length
                + ",\"kind\":\"image\",\"width\":1280,\"height\":720" + extra + "}";
    }

    /** A config enabling the feed with {@code keys} on {@code mirrors}. */
    static LauncherConfig config(List<String> mirrors, List<Key> keys, String extra) throws ContentException {
        StringBuilder keyList = new StringBuilder();
        for (Key key : keys) {
            if (keyList.length() > 0) keyList.append(',');
            keyList.append("{\"keyId\":\"").append(key.keyId).append("\",\"publicKey\":\"").append(key.publicKey).append("\"}");
        }
        StringBuilder mirrorList = new StringBuilder();
        for (String mirror : mirrors) {
            if (mirrorList.length() > 0) mirrorList.append(',');
            mirrorList.append('"').append(mirror).append('"');
        }
        return LauncherConfig.parse(utf8("{\"schema\":1,\"newsFeed\":{\"enabled\":true,\"mirrors\":[" + mirrorList
                + "],\"keys\":[" + keyList + "]" + extra + "}}"));
    }

    static long at(String timestamp) {
        return Rfc3339.parse(timestamp);
    }
}
